// spec: specs/search-header-cta.md (1.4, 1.5) · кейс: .qa/tests/search-header-cta/MORE-01.md
// seed: tests/seed.spec.ts (гость) · Android (Pixel 7) · прод, только просмотр.
import { test, expect } from '@playwright/test';
import { prepareReadOnly, openResults, categoryUrl, queryUrl, waitMoreBlock, listingIds, LOAD } from './search-cta.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('«עסקים נוספים שעשויים לעניין אותך» после результатов /search', () => {
  test('Категория: блок после результатов, без повторов результатов, догружается при прокрутке #839121 @android @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);
    await openResults(page, categoryUrl());
    await waitMoreBlock(page);

    const results = await listingIds(page, false);
    const first = await listingIds(page, true);
    expect(results.length, 'в категории есть результаты').toBeGreaterThan(0);
    expect(first.filter((id) => results.includes(id)), 'карточки блока не повторяют результаты категории').toEqual([]);

    await page.locator('a[href*="source=search_more_listings"]').last().scrollIntoViewIfNeeded();
    await expect
      .poll(async () => (await listingIds(page, true)).length, { ...LOAD, message: 'блок догружается при прокрутке' })
      .toBeGreaterThan(first.length);
  });

  test('Свободный поиск (?q=): блок «עסקים נוספים» тоже есть #839121 @android @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);
    await openResults(page, queryUrl());
    await waitMoreBlock(page);
  });
});
